const input = $input.first().json;

const data = input.timeline || [];

if (data.length < 2) {
  return [
    {
      json: {
        error: true,
        message: "Not enough timeline data"
      }
    }
  ];
}

// Sort timeline by date
data.sort((a, b) => {
  return new Date(a.date) - new Date(b.date);
});

// Latest day
const latest = data[data.length - 1];

// Previous 7 days
const previousData = data.slice(-8, -1);

// Calculate 7-day baseline
const baselineValues = previousData
  .map(item => Number(item.value || 0))
  .filter(value => !isNaN(value));

const sevenDayBaseline =
  baselineValues.reduce((sum, value) => sum + value, 0) /
  baselineValues.length;

// Current volume
const currentVolume = Number(latest.value || 0);

// Calculate spike %
const spikePercentage =
  sevenDayBaseline > 0
    ? ((currentVolume - sevenDayBaseline) / sevenDayBaseline) * 100
    : 0;

// Spike threshold
const spikeThreshold = 50;

// Detect spike
const spikeDetected =
  spikePercentage >= spikeThreshold;

return [
  {
    json: {
      theme: input.theme,
      sector: input.sector,
      watchlistTickers: input.watchlistTickers,

      latestDate: latest.date,

      currentVolume: currentVolume,

      sevenDayBaseline: Number(
        sevenDayBaseline.toFixed(2)
      ),

      spikePercentage: Number(
        spikePercentage.toFixed(2)
      ),

      spikeThreshold: spikeThreshold,

      spikeDetected: spikeDetected,

      timeline: data
    }
  }
];

const data = $input.first().json;

const spike = Number(data.spikePercentage || 0);

let severity;

if (spike >= 100) {
  severity = "HIGH";
} else if (spike >= 50) {
  severity = "MEDIUM";
} else {
  severity = "LOW";
}

return [
  {
    json: {
      ...data,
      severity
    }
  }
];

const data = $input.first().json;

let eventType = "OTHER";

const theme = (data.theme || "").toLowerCase();

if (
  theme.includes("semiconductor") ||
  theme.includes("chip") ||
  theme.includes("export")
) {
  eventType = "TRADE / SEMICONDUCTOR";
} else if (
  theme.includes("oil") ||
  theme.includes("energy")
) {
  eventType = "ENERGY";
} else if (
  theme.includes("shipping") ||
  theme.includes("supply")
) {
  eventType = "SUPPLY CHAIN";
}

return [
  {
    json: {
      ...data,
      eventType
    }
  }
];

const input = $input.first().json;

const text = input.content?.parts?.[0]?.text || "";

if (!text) {
  return [
    {
      json: {
        error: true,
        message: "Gemini returned empty response"
      }
    }
  ];
}

const cleanedText = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let result;

try {
  result = JSON.parse(cleanedText);
} catch (error) {
  return [
    {
      json: {
        error: true,
        message: "Unable to parse Gemini JSON",
        rawResponse: text
      }
    }
  ];
}

return [
  {
    json: {
      // Original event information
      theme: input.theme,
      sector: input.sector,
      eventType: input.eventType,
      watchlistTickers: input.watchlistTickers,
      latestDate: input.latestDate,
      currentVolume: input.currentVolume,
      sevenDayBaseline: input.sevenDayBaseline,
      spikePercentage: input.spikePercentage,
      spikeThreshold: input.spikeThreshold,
      spikeDetected: input.spikeDetected,

      // Gemini analysis
      eventSummary: result.eventSummary,
      narrative: result.narrative,
      sectorImpact: result.sectorImpact,
      severity: result.severity,
      tickerImpacts: result.tickerImpacts,
      marketImplication: result.marketImplication,
      disclaimer: result.disclaimer
    }
  }
];
